<?php
namespace qqworld_collector; class advanced_cache { public function __construct() { if ( !$this->is_allow_to_load_cache() ) return; $cache_file = $this->get_cache_file(); if ($cache_file) { include $cache_file; exit; } } private function is_allow_to_load_cache() { if (defined('WP_CLI') && WP_CLI) return false; if ($_SERVER['REQUEST_METHOD'] == 'POST') return false; if (isset($_SERVER['QUERY_STRING']) && $_SERVER['QUERY_STRING']) return false; if (preg_match('/\/wp\-admin\/|\/wp\-content\/|\/wp\-includes\//i', $_SERVER['REQUEST_URI'])) return false; if (preg_match('/^\/wp-json\//i', $_SERVER['REQUEST_URI'])) { if (preg_match('/^\/wp-json\/cs/i', $_SERVER['REQUEST_URI'])) { $cache_file = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . 'cs' . DIRECTORY_SEPARATOR . md5($_SERVER['REQUEST_URI']); if (file_exists($cache_file)) { include $cache_file; exit; } } return false; } $cookie = implode('', array_keys($_COOKIE)); if (strstr($cookie, 'wordpress_logged_in_') !== false) return false; return true; } private function get_cache_file() { $cache_file = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($_SERVER['REQUEST_URI']); if (file_exists($cache_file)) { $time = filemtime($cache_file); if (time() - $time < QQWORLD_STATIC_CACHE_EXPIRATION_TIME) { return $cache_file; } else { ob_start(array($this, 'make_cache')); add_action( 'wp_after_admin_bar_render', function() { ob_end_flush(); }); } } return false; } public function make_cache($buffer) { $cache_file = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($_SERVER['REQUEST_URI']); if ($buffer) file_put_contents($cache_file, $buffer); return $buffer; } } new advanced_cache;